// Minh họa: Thiết lập Quality Gate (QA Process) tự động hóa trong CI bằng Vitest
import { describe, it, expect } from 'vitest';

// Hệ thống tính toán hóa đơn thương mại điện tử
export function calculateOrderTotal(subtotal: number, taxRate: number, discountPercent: number): number {
  if (subtotal < 0 || taxRate < 0 || discountPercent < 0 || discountPercent > 100) {
    throw new Error('Tham số tính toán không hợp lệ');
  }
  const discountedSubtotal = subtotal * (1 - discountPercent / 100);
  const taxAmount = discountedSubtotal * (taxRate / 100);
  return Number((discountedSubtotal + taxAmount).toFixed(2));
}

// QC Execution: Unit Test xác minh sản phẩm đáp ứng đúng nghiệp vụ
describe('Quality Control: calculateOrderTotal Unit Tests', () => {
  it('tính toán chính xác tổng tiền với thuế và chiết khấu hợp lệ', () => {
    const total = calculateOrderTotal(100, 10, 20); // 100 - 20% = 80; thuế 10% = 8 -> 88
    expect(total).toBe(88.00);
  });

  it('ném ngoại lệ khi discountPercent vượt quá 100 (Prevent Edge-case Defect)', () => {
    expect(() => calculateOrderTotal(100, 10, 105)).toThrowError('Tham số tính toán không hợp lệ');
  });
});

// Minh họa: Test cấp độ Integration Testing tương ứng với Kiến trúc Module trong TypeScript
import { describe, it, expect, vi } from 'vitest';

// Module User Repository & Notification Service
interface UserRepository {
  findById(id: string): Promise<{ id: string; email: string } | null>;
}
interface NotificationGateway {
  sendWelcomeEmail(email: string): Promise<boolean>;
}

// System Module: User Registration Workflow
class UserOnboardingWorkflow {
  constructor(
    private userRepo: UserRepository,
    private notifier: NotificationGateway
  ) {}

  async onboardUser(userId: string): Promise<boolean> {
    const user = await this.userRepo.findById(userId);
    if (!user) throw new Error('User not found');
    return this.notifier.sendWelcomeEmail(user.email);
  }
}

// V-Model Integration Test: Xác minh sự phối hợp giữa 2 module con
describe('V-Model Architecture Validation: UserOnboardingWorkflow', () => {
  it('tích hợp thành công giữa UserRepo và NotificationGateway', async () => {
    const mockRepo: UserRepository = {
      findById: vi.fn().mockResolvedValue({ id: 'u123', email: 'tester@enterprise.com' })
    };
    const mockNotifier: NotificationGateway = {
      sendWelcomeEmail: vi.fn().mockResolvedValue(true)
    };

    const workflow = new UserOnboardingWorkflow(mockRepo, mockNotifier);
    const result = await workflow.onboardUser('u123');

    expect(result).toBe(true);
    expect(mockNotifier.sendWelcomeEmail).toHaveBeenCalledWith('tester@enterprise.com');
  });
});

// Minh họa: Grey-box Testing cho API Authenticated bằng Vitest & Supertest logic
import { describe, it, expect, vi } from 'vitest';

// Giả lập backend endpoint với nội bộ có kiểm tra Cache và Database (Grey-box insight)
interface SessionDatabase {
  isValidToken(token: string): boolean;
  getUserRole(token: string): string;
}

export function handleAdminResourceRequest(token: string, db: SessionDatabase) {
  // Grey-box tester biết rằng hàm này kiểm tra token trong DB rồi kiểm tra quyền 'ADMIN'
  if (!db.isValidToken(token)) {
    return { status: 401, body: { error: 'Unauthorized' } };
  }
  if (db.getUserRole(token) !== 'ADMIN') {
    return { status: 403, body: { error: 'Forbidden: Insufficient privileges' } };
  }
  return { status: 200, body: { data: 'Secret Admin Payload' } };
}

describe('Grey-box Test: handleAdminResourceRequest', () => {
  it('trả về 403 khi token hợp lệ nhưng role là USER thường (dựa vào cấu trúc RBAC nội bộ)', () => {
    const mockDb: SessionDatabase = {
      isValidToken: vi.fn().mockReturnValue(true),
      getUserRole: vi.fn().mockReturnValue('USER') // Giả lập role từ database
    };

    const response = handleAdminResourceRequest('valid-user-token', mockDb);
    expect(response.status).toBe(403);
    expect(response.body.error).toContain('Forbidden');
  });
});

// Test Suite tự động hóa kiểm thử Giá trị biên (BVA) cho hàm Validate Tuổi bằng Vitest
import { describe, it, expect } from 'vitest';

export function validateUserAge(age: number): boolean {
  // Yêu cầu: Tuổi từ 18 đến 60 (bao gồm cả 18 và 60)
  return Number.isInteger(age) && age >= 18 && age <= 60;
}

describe('Boundary Value Analysis (BVA) - Age Validation [18, 60]', () => {
  // Kiểm thử biên dưới: 17 (Min-1), 18 (Min), 19 (Min+1)
  it('xác minh giá trị biên dưới', () => {
    expect(validateUserAge(17)).toBe(false); // Just Below Boundary
    expect(validateUserAge(18)).toBe(true);  // Exactly Lower Boundary
    expect(validateUserAge(19)).toBe(true);  // Just Above Boundary
  });

  // Kiểm thử biên trên: 59 (Max-1), 60 (Max), 61 (Max+1)
  it('xác minh giá trị biên trên', () => {
    expect(validateUserAge(59)).toBe(true);  // Just Below Boundary
    expect(validateUserAge(60)).toBe(true);  // Exactly Upper Boundary
    expect(validateUserAge(61)).toBe(false); // Just Above Boundary
  });

  // Kiểm thử biên cực đoan (Robustness / Extreme Edge Cases)
  it('xác minh các giá trị biên dị thường', () => {
    expect(validateUserAge(0)).toBe(false);
    expect(validateUserAge(-1)).toBe(false);
    expect(validateUserAge(18.5)).toBe(false); // Số thực không phải số nguyên
  });
});

// Test Suite áp dụng Phân Vùng Tương Đương (EP) với Vitest test.each
import { describe, it, expect } from 'vitest';

export type StudentGrade = 'TRUOT' | 'KHA' | 'GIOI';

export function calculateGrade(score: number): StudentGrade {
  if (typeof score !== 'number' || isNaN(score) || score < 0 || score > 100) {
    throw new Error('Điểm số phải là số thực từ 0 đến 100');
  }
  if (score < 50) return 'TRUOT';
  if (score < 80) return 'KHA';
  return 'GIOI';
}

describe('Equivalence Partitioning (EP) - Grade Evaluation', () => {
  // 1. Kiểm thử các phân vùng HỢP LỆ (Valid Classes) bằng giá trị đại diện
  it.each([
    { score: 25, expected: 'TRUOT', partition: 'Valid Partition [0..49]' },
    { score: 65, expected: 'KHA',   partition: 'Valid Partition [50..79]' },
    { score: 90, expected: 'GIOI',  partition: 'Valid Partition [80..100]' },
  ])('chấm đúng kết quả $expected cho đại diện $partition (score: $score)', ({ score, expected }) => {
    expect(calculateGrade(score)).toBe(expected);
  });

  // 2. Kiểm thử các phân vùng KHÔNG HỢP LỆ (Invalid Classes)
  it.each([
    { score: -15, label: 'Điểm âm (< 0)' },
    { score: 150, label: 'Điểm vượt ngưỡng (> 100)' },
    { score: NaN, label: 'Not a Number (NaN)' },
  ])('ném lỗi cho phân vùng không hợp lệ: $label', ({ score }) => {
    expect(() => calculateGrade(score)).toThrowError();
  });
});

// Test Suite tự động hóa kiểm thử Bảng Quyết Định (Decision Table) bằng Vitest
import { describe, it, expect } from 'vitest';

interface CheckoutContext {
  isVip: boolean;
  orderTotal: number;
  hasCoupon: boolean;
}

// Hàm tính phí vận chuyển và áp dụng quà tặng theo Decision Table
export function evaluateOrderBenefit(ctx: CheckoutContext): { freeShipping: boolean; gift: boolean } {
  const isHighValue = ctx.orderTotal >= 500;

  // Rule 1: VIP + HighValue -> Free Shipping + Gift
  if (ctx.isVip && isHighValue) return { freeShipping: true, gift: true };
  // Rule 2: VIP + Coupon -> Free Shipping, no gift
  if (ctx.isVip && ctx.hasCoupon) return { freeShipping: true, gift: false };
  // Rule 3: Regular + HighValue + Coupon -> Free Shipping, no gift
  if (!ctx.isVip && isHighValue && ctx.hasCoupon) return { freeShipping: true, gift: false };

  // Rule 4 (Default): Phí thường, không quà
  return { freeShipping: false, gift: false };
}

describe('Decision Table Testing: evaluateOrderBenefit', () => {
  it.each([
    // Rule 1: VIP=T, HighValue=T, Coupon=* -> FreeShip=T, Gift=T
    { ctx: { isVip: true, orderTotal: 600, hasCoupon: false }, expected: { freeShipping: true, gift: true }, rule: 'Rule 1: VIP High Value' },
    // Rule 2: VIP=T, HighValue=F, Coupon=T -> FreeShip=T, Gift=F
    { ctx: { isVip: true, orderTotal: 200, hasCoupon: true }, expected: { freeShipping: true, gift: false }, rule: 'Rule 2: VIP with Coupon' },
    // Rule 3: VIP=F, HighValue=T, Coupon=T -> FreeShip=T, Gift=F
    { ctx: { isVip: false, orderTotal: 700, hasCoupon: true }, expected: { freeShipping: true, gift: false }, rule: 'Rule 3: Non-VIP High with Coupon' },
    // Rule 4: VIP=F, HighValue=F, Coupon=F -> FreeShip=F, Gift=F
    { ctx: { isVip: false, orderTotal: 100, hasCoupon: false }, expected: { freeShipping: false, gift: false }, rule: 'Rule 4: Default Regular' },
  ])('thực thi đúng cho $rule', ({ ctx, expected }) => {
    expect(evaluateOrderBenefit(ctx)).toEqual(expected);
  });
});

