// Mô hình hóa Bug State Machine bằng TypeScript enum và transitions logic
export type BugState = 
  | 'NEW' 
  | 'ASSIGNED' 
  | 'FIXED' 
  | 'RETEST' 
  | 'CLOSED' 
  | 'REOPENED' 
  | 'REJECTED';

export class BugLifecycleManager {
  private currentState: BugState = 'NEW';

  getState(): BugState {
    return this.currentState;
  }

  transition(action: 'ASSIGN' | 'FIX' | 'DEPLOY_TEST' | 'VERIFY_PASS' | 'VERIFY_FAIL' | 'REJECT'): void {
    switch (this.currentState) {
      case 'NEW':
      case 'REOPENED':
        if (action === 'ASSIGN') this.currentState = 'ASSIGNED';
        if (action === 'REJECT') this.currentState = 'REJECTED';
        break;
      case 'ASSIGNED':
        if (action === 'FIX') this.currentState = 'FIXED';
        if (action === 'REJECT') this.currentState = 'REJECTED';
        break;
      case 'FIXED':
        if (action === 'DEPLOY_TEST') this.currentState = 'RETEST';
        break;
      case 'RETEST':
        if (action === 'VERIFY_PASS') this.currentState = 'CLOSED';
        if (action === 'VERIFY_FAIL') this.currentState = 'REOPENED';
        break;
      case 'CLOSED':
      case 'REJECTED':
        if (action === 'ASSIGN') this.currentState = 'REOPENED';
        break;
    }
  }
}

