// Regression Test Case bảo vệ tính năng giỏ hàng không bị hỏng sau khi cập nhật mã voucher
import { describe, it, expect } from 'vitest';

class ShoppingCart {
  private items: Array<{ id: string; price: number }> = [];
  private discount: number = 0;

  addItem(id: string, price: number) { this.items.push({ id, price }); }
  applyVoucher(code: string) {
    if (code === 'SUMMER10') this.discount = 10;
  }
  getTotal(): number {
    const rawTotal = this.items.reduce((sum, item) => sum + item.price, 0);
    return Math.max(0, rawTotal - this.discount);
  }
}

describe('Regression Suite: Shopping Cart Core Calculations', () => {
  it('REG-01: Thêm sản phẩm và tính tổng tiền chuẩn xác (Core feature bảo vệ qua các sprint)', () => {
    const cart = new ShoppingCart();
    cart.addItem('item-1', 50);
    cart.addItem('item-2', 30);
    expect(cart.getTotal()).toBe(80);
  });

  it('REG-02: Áp dụng voucher không được làm tổng tiền bị âm (Bảo vệ lỗi bug cũ đã từng bị phát hiện)', () => {
    const cart = new ShoppingCart();
    cart.addItem('item-1', 5);
    cart.applyVoucher('SUMMER10'); // Giảm 10 khi giỏ hàng chỉ có 5
    expect(cart.getTotal()).toBe(0); // Không được phép ra -5
  });
});

