// Tính toán tài chính là ứng viên số 1 BẮT BUỘC phải làm Automation vì rủi ro cao và lặp lại liên tục
export function calculateCompoundInterest(principal: number, annualRate: number, years: number): number {
  return Number((principal * Math.pow(1 + annualRate / 100, years)).toFixed(2));
}

describe('Automation Essential: Financial Interest Calculations', () => {
