// Triển khai Page Object Model (POM) chuẩn mực bằng Playwright và TypeScript
import { Page, Locator, expect } from '@playwright/test';

// 1. PAGE OBJECT CLASS: Đóng gói Selectors và Actions của màn hình Đăng Nhập
export class LoginPage {
  readonly page: Page;
  readonly emailInput: Locator;
  readonly passwordInput: Locator;
  readonly submitButton: Locator;
  readonly errorMessage: Locator;

  constructor(page: Page) {
    this.page = page;
    this.emailInput = page.getByLabel('Email address');
    this.passwordInput = page.getByLabel('Password');
    this.submitButton = page.getByRole('button', { name: 'Sign in' });
    this.errorMessage = page.locator('[role="alert"]');
  }

  async goto() {
    await this.page.goto('/login');
  }

  async login(email: string, pass: string) {
    await this.emailInput.fill(email);
    await this.passwordInput.fill(pass);
    await this.submitButton.click();
  }
}

// 2. TEST SPEC: Kịch bản test sạch sẽ, tách biệt hoàn toàn khỏi selectors
export async function runLoginTest(page: Page) {
  const loginPage = new LoginPage(page);
  await loginPage.goto();
  await loginPage.login('invalid@enterprise.com', 'wrongpassword');
  await expect(loginPage.errorMessage).toContainText('Invalid credentials');
}

