// So sánh cơ chế Chờ đợi (Wait Strategies) trong TypeScript
import { Page, expect } from '@playwright/test';

export async function demonstrateWaitStrategies(page: Page) {
  // 1. TỒI TỆ NHẤT: Hard Sleep (Anti-pattern tuyệt đối cấm trong production)
  // await new Promise(r => setTimeout(r, 5000)); // Lãng phí tài nguyên và gây flaky

  // 2. TIÊU CHUẨN: Explicit Wait cho một trạng thái cụ thể
  const submitBtn = page.getByRole('button', { name: 'Thanh toán' });
  await submitBtn.waitFor({ state: 'visible', timeout: 5000 });

  // 3. NÂNG CAO: Chờ trạng thái mạng API hoàn tất (Custom Condition Wait)
  await Promise.all([
    page.waitForResponse(res => res.url().includes('/api/checkout') && res.status() === 200),
    submitBtn.click()
  ]);

  // 4. Fluent Web Assertion: Tự động poll liên tục cho đến khi nội dung thay đổi đúng
  await expect(page.locator('.toast-success')).toHaveText('Giao dịch thành công!', { timeout: 3000 });
}

