// Giả lập hàm làm sạch đầu vào (Sanitize Input) an toàn
export function sanitizeSearchQuery(input: string): string {
  // Thay thế các ký tự HTML nguy hiểm để chống Reflected XSS
  return input
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#x27;');
}

describe('Security Baseline Testing: Input Sanitization', () => {
  it('SEC-01: Triệt tiêu XSS Script Tag trong ô tìm kiếm', () => {
