    const sanitized = sanitizeSearchQuery(maliciousPayload);

    // Đảm bảo không còn thẻ <script> có thể thực thi được
    expect(sanitized).not.toContain('<script>');
    expect(sanitized).toBe('&lt;script&gt;alert(document.cookie)&lt;/script&gt;');
  });

  it('SEC-02: Kiểm tra các payload Injection dị thường dạng img onerror', () => {
    const imgPayload = '<img src="invalid" onerror="alert(1)">';
    const sanitized = sanitizeSearchQuery(imgPayload);
    expect(sanitized).not.toContain('<img');
  });
});

