// Giải quyết Flaky Test do phụ thuộc Thời Gian (Clock-dependent) bằng Fake Timers trong Vitest
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';

// Hàm gửi cảnh báo nếu sau 30 giây người dùng không xác nhận
class SessionTimeoutWatcher {
  private timer: any;
  public timedOut = false;

  startWatch(callback: () => void) {
    this.timer = setTimeout(() => {
      this.timedOut = true;
      callback();
    }, 30000); // 30 giây
  }

  cancel() { clearTimeout(this.timer); }
}

describe('Triệt tiêu Flakiness bằng cách điều khiển thời gian ảo (Deterministic Testing)', () => {
  beforeEach(() => {
    vi.useFakeTimers(); // Thay thế đồng hồ thật của OS bằng đồng hồ ảo của Vitest
  });

  afterEach(() => {
    vi.useRealTimers(); // Khôi phục lại trạng thái chuẩn
  });

  it('kích hoạt timeout chính xác sau 30 giây mà KHÔNG CẦN CHỜ ĐỢI THẬT (Chạy trong 1ms)', () => {
    const watcher = new SessionTimeoutWatcher();
    const timeoutSpy = vi.fn();

    watcher.startWatch(timeoutSpy);

    // Chưa tới thời gian -> Không được gọi
    vi.advanceTimersByTime(29999);
    expect(timeoutSpy).not.toHaveBeenCalled();

    // Tua đúng 1ms nữa chạm mốc 30,000ms -> Kích hoạt ngay lập tức
    vi.advanceTimersByTime(1);
    expect(timeoutSpy).toHaveBeenCalledTimes(1);
    expect(watcher.timedOut).toBe(true);
  });
});

