// Mô phỏng cấu trúc Pact Contract JSON được sinh ra từ Consumer
interface PactContractInteraction {
  description: string;
  request: {
    method: 'GET';
    path: '/api/v1/users/123';
    headers: { Authorization: string };
  };
  response: {
    status: 200;
    headers: { 'Content-Type': 'application/json' };
    body: {
      id: string;
      email: string;
      tier: 'FREE' | 'VIP'; // Consumer CHỈ quan tâm 3 trường này, không quan tâm 20 trường khác
    };
  };
}

// 1. Phía Consumer: Khai báo Contract kỳ vọng
export const userContract: PactContractInteraction = {
  description: 'Yêu cầu lấy thông tin người dùng ID 123 cho trang Checkout',
  request: {
    method: 'GET',
    path: '/api/v1/users/123',
    headers: { Authorization: 'Bearer mock-token' }
  },
  response: {
    status: 200,
    headers: { 'Content-Type': 'application/json' },
    body: { id: '123', email: 'alice@enterprise.com', tier: 'VIP' }
  }
};

// 2. Phía Provider: Xác minh API thực tế có đáp ứng đúng Contract không trong CI của Provider
export function verifyProviderContract(actualProviderResponse: any, contract: PactContractInteraction): boolean {
  // Provider có thể trả về 50 trường, nhưng BẮT BUỘC phải có đủ các trường Consumer yêu cầu
  const body = actualProviderResponse.body;
  const isMatch = body.id === contract.response.body.id &&
                  typeof body.email === 'string' &&
                  ['FREE', 'VIP'].includes(body.tier);
  return isMatch && actualProviderResponse.status === contract.response.status;
}

