// 1. BDD SPECIFICATION: Viết bằng cú pháp Gherkin tự nhiên (features/atm_withdrawal.feature)
/*
Feature: Rút tiền mặt tại cây ATM
  Scenario: Rút tiền thành công khi tài khoản đủ số dư
    Given Tài khoản người dùng có số dư ban đầu là 1000 USD
    When Người dùng thực hiện rút 200 USD từ cây ATM
    Then Cây ATM nhả ra số tiền 200 USD
    And Số dư tài khoản người dùng còn lại 800 USD
*/

// 2. BDD STEP DEFINITIONS: Mã TypeScript ánh xạ các bước Gherkin thành code thực thi
import { describe, it, expect } from 'vitest';

class BankAccount {
  constructor(public balance: number) {}
  withdraw(amount: number): number {
    if (this.balance >= amount) {
      this.balance -= amount;
      return amount;
    }
    throw new Error('Số dư không đủ');
  }
}

describe('BDD Step Definition: ATM Cash Withdrawal', () => {
  it('Scenario: Rút tiền thành công khi tài khoản đủ số dư', () => {
    // Given: Ngữ cảnh
    const account = new BankAccount(1000);

    // When: Hành động
    const dispensedCash = account.withdraw(200);

    // Then & And: Kết quả kỳ vọng
    expect(dispensedCash).toBe(200);
    expect(account.balance).toBe(800);
  });
});

// Triển khai Canary Feature Flag logic an toàn cho Shift-Right Testing trong TypeScript
export interface UserSession {
  userId: string;
  country: string;
  isBetaTester: boolean;
}

export class ProductionFeatureFlagService {
  // Kiểm tra user có được kích hoạt tính năng Checkout V2 trên Production hay không
  static isCheckoutV2Enabled(user: UserSession, rolloutPercentage = 5): boolean {
    // 1. Luôn kích hoạt cho nhóm Beta Testers nội bộ công ty
    if (user.isBetaTester) return true;

    // 2. Hash User ID để phân bổ nhất quán vào nhóm phần trăm (Consistent Hashing)
    const hash = this.simpleHash(user.userId);
    const bucket = hash % 100; // Giá trị từ 0 đến 99

    // Chỉ kích hoạt nếu rơi vào nhóm tỷ lệ rollout hiện tại (ví dụ 5%)
    return bucket < rolloutPercentage;
  }

  private static simpleHash(str: string): number {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      hash = ((hash << 5) - hash) + str.charCodeAt(i);
      hash |= 0;
    }
    return Math.abs(hash);
  }
}

