// 1. KIỂM THỬ TIỀN TỆ: Tránh thảm họa Floating Point bằng cách tính theo đơn vị Cent
export function calculatePreciseTotal(pricesInCents: number[]): number {
  // Thay vì cộng 19.99 + 10.05 (gây ra 30.040000000000003)
  // Ta cộng theo đơn vị nhỏ nhất là Cents (1999 + 1005 = 3004 cents -> 30.04$)
  const totalCents = pricesInCents.reduce((acc, curr) => acc + curr, 0);
  return totalCents / 100;
}

// 2. KIỂM THỬ MÚI GIỜ: Kiểm tra xác định ngày giao dịch chuẩn quốc tế
export function getTransactionDateInUtc(isoTimestamp: string): string {
  const date = new Date(isoTimestamp);
  return date.toISOString().split('T')[0]; // Luôn lấy ngày theo UTC
}

