// Script kiểm tra sức khỏe hệ thống trong khi đang diễn ra thử nghiệm Chaos
export async function verifySteadyStateDuringChaos(): Promise<boolean> {
  // Bắn 100 requests liên tục trong khi Chaos Mesh đang kill Pods ngầm
  const results = await Promise.all(
    Array.from({ length: 100 }, async () => {
      try {
        const res = await fetch('https://staging.enterprise.com/api/healthz');
        return res.status === 200;
      } catch {
        return false;
      }
    })
  );

  const successCount = results.filter(Boolean).length;
  // Giả định Resilience: Ít nhất 99% requests phải thành công nhờ Retry & Load Balancer failover
  return successCount >= 99;
}

