  });
});

// Chương trình tính toán bộ Quality Metrics tự động từ dữ liệu Jira & Sentry
export interface SprintQualityData {
  sprintName: string;
  totalStoryPoints: number;
  internalBugsFound: number;   // Bug phát hiện bởi QA trong sprint
  productionBugsReported: number; // Bug khách hàng khiếu nại trên Production
  totalIncidentsTimeMinutes: number; // Tổng thời gian gián đoạn hệ thống
  totalIncidentsCount: number;
}

export interface QualityMetricsReport {
  defectDensity: number;       // Bug per Story Point
  defectLeakageRate: string;   // Tỷ lệ % lỗi lọt ra Production
  mttrMinutes: number;         // Thời gian trung bình giải quyết sự cố
  healthEvaluation: 'EXCELLENT' | 'HEALTHY' | 'NEEDS_IMPROVEMENT';
}

export function calculateQualityMetrics(data: SprintQualityData): QualityMetricsReport {
  const totalBugs = data.internalBugsFound + data.productionBugsReported;

  // 1. Defect Density = Tổng lỗi / Tổng Story Points
  const defectDensity = Number((totalBugs / data.totalStoryPoints).toFixed(2));

  // 2. Defect Leakage = (Lỗi Production / Tổng lỗi) * 100
  const leakagePercentage = totalBugs > 0 ? (data.productionBugsReported / totalBugs) * 100 : 0;
  const defectLeakageRate = `${leakagePercentage.toFixed(1)}%`;

  // 3. MTTR = Tổng thời gian giải quyết / Số sự cố
  const mttrMinutes = data.totalIncidentsCount > 0 
    ? Math.round(data.totalIncidentsTimeMinutes / data.totalIncidentsCount) 
    : 0;

  // Đánh giá sức khỏe tổng quan
  let healthEvaluation: 'EXCELLENT' | 'HEALTHY' | 'NEEDS_IMPROVEMENT' = 'HEALTHY';
  if (leakagePercentage < 5 && mttrMinutes < 30) healthEvaluation = 'EXCELLENT';
  if (leakagePercentage > 15 || mttrMinutes > 120) healthEvaluation = 'NEEDS_IMPROVEMENT';

  return { defectDensity, defectLeakageRate, mttrMinutes, healthEvaluation };
}
